function neighbours(p){const group=groups[p.region],at=group.indexOf(p),globalAt=pages.indexOf(p);return pages.filter(x=>x!==p).sort((a,b)=>{const as=a.region===p.region?0:1,bs=b.region===p.region?0:1;if(as!==bs)return as-bs;if(!as)return Math.abs(group.indexOf(a)-at)-Math.abs(group.indexOf(b)-at);return Math.abs(pages.indexOf(a)-globalAt)-Math.abs(pages.indexOf(b)-globalAt);}).slice(0,10);}
function faqs(p,i){const bank=[
[`Can I request house cleaning anywhere in ${p.name}?`,`Maid At Home accepts booking requests across ${p.name}, subject to the exact address, preferred date and a suitable cleaner route. Because local arrival can involve ${p.access}, include entry instructions before confirmation. Availability is checked for the selected service rather than assumed from the suburb name alone.`],
[`What access details matter for a ${p.name} booking?`,`For a ${p.name} appointment, describe ${p.access} when submitting the booking. Add the intercom, key, gate, lift, stair or contact instructions that apply to your property. Accurate directions reduce waiting at arrival and protect the time reserved for the rooms and tasks selected.`],
[`How should parking be explained for cleaning in ${p.name}?`,`Parking should be described before the cleaner travels to ${p.name}, where the practical options can include ${p.parking}. State whether a driveway, visitor bay, permit, loading space or paid facility is available. If unloading involves distance or timing limits, the team can plan equipment and arrival more realistically.`],
[`Which cleaning service is suitable in ${p.name}?`,`The right starting point depends on condition and priorities, not only the postcode. A ${p.name} request may involve ${p.focus}. Standard Clean suits maintained rooms, Deep Clean allows more detail, Hourly Clean targets an agreed list, and moving services suit appropriately prepared empty properties.`],
[`Can ${p.name} households arrange recurring cleaning?`,`Weekly, fortnightly, three-weekly and four-weekly cleaning can be requested in ${p.name} when an ongoing route is available. A useful frequency depends on household activity, room count and priorities. Eligible recurring Standard or Deep bookings receive the published saving after the first completed service.`],
[`What should I mention before carpet cleaning in ${p.name}?`,`Before carpet steam cleaning in ${p.name}, tell us about ${p.carpet}. Confirm room count, visible stains, fibre concerns, furniture, power and water access. Carpet treatment is separate from routine vacuuming, and normal foot traffic should wait until the cleaned fibres have dried sufficiently.`],
[`How do I prepare a move clean in ${p.name}?`,`A Move In or End of Lease request in ${p.name} should include property condition, vacancy timing and the access window. Explain ${p.parking}, attach any relevant agent checklist and say whether carpet steam cleaning is required. Reviewing these details early protects the booked cleaning scope.`],
[`Do I provide equipment for a clean in ${p.name}?`,`Notes for a ${p.name} property should confirm whether a suitable vacuum and mop are available for its floors. Maid At Home can organise professional products, while equipment arrangements depend on the service. Mention stairs, lifts or long paths because ${p.access} can affect what is carried efficiently.`]
];const start=i%bank.length;return Array.from({length:6},(_,j)=>bank[(start+j)%bank.length]);}
