function diversify(value, pageIndex, sectionSeed=0){
  let result=value;
  phraseVariants.forEach(([needle,variants],phraseIndex)=>{
    let hash = Math.imul(pageIndex + 1, 0x9e3779b1) ^ Math.imul(phraseIndex + 1, 0x85ebca6b) ^ Math.imul(sectionSeed + 1, 0xc2b2ae35);
    hash ^= hash >>> 16;
    hash = Math.imul(hash, 0x7feb352d);
    hash ^= hash >>> 15;
    const pick=(hash >>> 0)%variants.length;
    result=result.replace(new RegExp(needle.replace(/[.*+?^${}()|[\]\\]/g,'\\$&'),'gi'),variants[pick]);
  });
  return result;
}
